/** GHS-POP, THE JRC'S GLOBAL POPULATION GRID, READ FOR THE STUDY AREA ONLY (TODO 24, 2026-11-11). The practitioner
 *  confirmed GHSL as the JRC's Global Human Settlement Layer. JRC keeps the R2023A grids on AWS as cloud-optimized
 *  GeoTIFFs: measured 2026-11-11 from one 16 KB read of the 2020 file's header, 432,002 x 213,822 cells at 3 arc-seconds,
 *  512 x 512 tiles, deflate, five overviews, the indexes before the data; the server answers ranges and sends CORS. So
 *  the window over a study area is read in parts, with nothing downloaded first: Raster input's URL path already does it. */
export const GHS_EPOCHS=['1975','1980','1985','1990','1995','2000','2005','2010','2015','2020','2025','2030'] as const;
export const GHS_PROJECTED=new Set(['2025','2030']);
export const ghsUrl=(epoch:string):string=>
  `https://jrc-ghsl.s3.amazonaws.com/ghs-pop/r2023a/4326/3asec/${epoch}/GHS_POP_E${epoch}_GLOBE_R2023A_4326_3ss_V1_0.tif`;
export const GHS_LICENCE='© European Union, 1995–2026. CC BY 4.0 (Commission Decision 2011/833/EU).';
export const GHS_CITATION='Schiavina M., Freire S., Carioli A., MacManus K. (2023): GHS-POP R2023A – GHS population grid multitemporal '
  +'(1975-2030). European Commission, Joint Research Centre. doi:10.2905/2FF68A52-5B5B-4A22-8F40-C41DA8332CFE; and Pesaresi M., '
  +'Schiavina M. et al. (2024). Advances on the Global Human Settlement Layer by joint assessment of Earth Observation and '
  +'population survey data. International Journal of Digital Earth 17(1). doi:10.1080/17538947.2024.2390454';
export const GHS_NOTE='Residential population: census counts spread over residential building volume, 3 arc-seconds (about 90 m), '
  +'warped from the 100 m Mollweide grid. Weaker where buildings are hard to see, which is often rural. Built from the same '
  +'buildings as GHS-BUILT, so the two should not be set against each other in one analysis.';
